<?php
$saved=$_SESSION['quote']??null;$number=max(1,min(20,(int)($_GET['companions']??1)));$products=q('SELECT code,name_fr,name_ar,price_tnd,commercial_approved FROM products WHERE active=1 ORDER BY id')->fetchAll();$opts=[];foreach($products as $p)$opts[$p['code']]=$p['name_'.lang()].' · '.($p['commercial_approved']?money((int)round((float)$p['price_tnd']*1000)):tr('En attente de validation','في انتظار الموافقة'));
