<?php form_start('/orders/preview');$owned=$user?q('SELECT c.id,c.name,c.serial_number FROM companions c JOIN companion_owners co ON co.companion_id=c.id WHERE co.user_id=? AND co.relationship="primary" ORDER BY c.id',[$user['id']])->fetchAll():[];
if($user&&in_array($user['role'],['professional','veterinarian'],true)){$owned=q('SELECT c.id,c.name,c.serial_number FROM companions c JOIN companion_owners co ON co.companion_id=c.id AND co.relationship="primary" JOIN professional_clients pc ON pc.customer_user_id=co.user_id WHERE pc.professional_user_id=? AND pc.consent_status="accepted" ORDER BY c.id',[$user['id']])->fetchAll();}
for($i=0;$i<$number;$i++){echo '<fieldset><legend>'.esc(tr('Compagnon','الرفيق')).' '.($i+1).'</legend>';select_field('items['.$i.'][product_code]','Produit','المنتج',$opts);if($owned){$animals=[''=>tr('Choisir une identité','اختر هوية')];foreach($owned as $c)$animals[$c['id']]=$c['name'].' · '.$c['serial_number'];select_field('items['.$i.'][companion_id]','Identité à équiper','الهوية',$animals,$_GET['companion_id']??'');$invites=q('SELECT i.id,i.name,c.name companion_name FROM companion_owner_invites i JOIN companions c ON c.id=i.companion_id JOIN companion_owners co ON co.companion_id=c.id WHERE co.user_id=? AND co.relationship="primary" AND i.status="confirmed"',[$user['id']])->fetchAll();$io=[''=>tr('Titulaire principal','المالك الرئيسي')];foreach($invites as $iv)$io[$iv['id']]=$iv['name'].' · '.$iv['companion_name'];select_field('items['.$i.'][owner_invite_id]','Titulaire de la carte','حامل البطاقة',$io);}echo '</fieldset>';}
field('promo_code','Code promo · facultatif','رمز تخفيض · اختياري');if($user&&in_array($user['role'],['professional','veterinarian'],true))check_field('professional_discount','Demander la remise professionnelle','طلب التخفيض المهني');form_end('Calculer mon devis','حساب السعر');
if($saved):$quote=$saved['quote']; ?><section class="quote-result"><h2><?=esc(tr('Votre devis','عرض السعر'))?></h2><?php detail_list([tr('Produits','المنتجات')=>money($quote['subtotal_millimes']),tr('Remises','التخفيضات')=>money($quote['discount_millimes']),tr('Livraison','التوصيل')=>money($quote['delivery_millimes']),tr('Total','المجموع')=>money($quote['total_millimes'])]);?><p><?=esc(tr('Valable 15 minutes. Les conditions sont vérifiées à nouveau lors de la confirmation.','صالح لمدة 15 دقيقة. تُراجع الشروط عند التأكيد.'))?></p><?php if($user):form_start('/orders');hidden('quote_id',$saved['quote_id']);hidden('idempotency_key',bin2hex(random_bytes(24)));$p=one('SELECT address FROM customer_profiles WHERE user_id=?',[$user['id']]);area('shipping_address','Adresse de livraison','عنوان التوصيل',$p['address']??'',true);form_end('Confirmer la commande','تأكيد الطلب');else: ?><a class="button" href="<?=esc(link_page('compte-type.html'))?>"><?=esc(tr('Créer une identité avant de commander','أنشئ هوية قبل الطلب'))?></a><?php endif ?></section><?php endif ?>
